export function ScrollTriggeredAnimation({
  property = "{{property}}",
  duration = {{duration}},
  loop = {{loop}},
  accent = "{{accent}}",
}) {
  const name = property === "colour" ? "mot-sta-colour" : "mot-sta-fill";
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ height: 10, background: "#24143014", borderRadius: 999, overflow: "hidden" }}>
        <span className="fill" style={{ display: "block", height: "100%", width: 0, borderRadius: 999, background: accent }} />
      </div>
      <p style={{ margin: "10px 0 0" }}>Progress fills as this section reaches the read position &middot; {property} &middot; {duration}ms</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .fill { animation: ${name} ${duration}ms ease-out ${loop ? "infinite" : 1} both; }
          @keyframes mot-sta-fill { from { width: 0%; } to { width: 100%; } }
          @keyframes mot-sta-colour { 0% { width: 100%; background: #241430; } 100% { width: 100%; background: #E8A020; } }
        }
      `}</style>
    </div>
  );
}
